function decorateChemistryQuestion(question,index,explanation) {
 const meta=CHEMISTRY_EXISTING_METADATA[question.topic][index];
 const unit=CHEMISTRY_SYLLABUS_2027[question.topic];
 const alternate=question.id.startsWith('v-');
 const sourceUnit=CHEMISTRY_SYLLABUS_2027[(alternate?meta.alternateSourceUnit:meta.sourceUnit)??question.topic];
 const slug=alternate?(meta.alternateSlug||meta.slug):meta.slug;
 const topic=sourceUnit.subtopics.find(item=>item.slug===slug);
 if(!topic)throw new Error(`Invalid syllabus link for ${question.id}`);
 const steps=Array.isArray(explanation)?explanation:[explanation,`Therefore, choose ${question.options[question.answer]}.`];
 return {...question,unitId:unit.id,syllabusUnitId:sourceUnit.id,subtopicId:topic.id,category:sourceUnit!==unit?'mixed':meta.category,difficulty:meta.difficulty,
  steps,explanation:steps.join(' '),syllabusVersion:'jee-main-2027',source:'Original practice'};
}
